        end_time_formatted: "2026-10-30 23:59",
        detail: "Emily Sailers and Amy Ray make up the GRAMMY®-winning duo The Indigo Girls. With 16 albums under their belt and 15 million records sold, The Indigo Girls stand as an icon in indie folk rock. This tour includes their friend, singer-songwriter and producer Linda Perry, former vocalist for 4 Non Blondes (“What’s Up?”). \n\nEmily and Amy cut their teeth gigging in bars and clubs in Atlanta in the late 80s. Despite their success, The Indigo Girls state in their bio that they’re “still a bar band at heart.” \nAmy and Emily met in elementary school in Decatur, GA. \nIn addition to her own songwriting, Linda Perry founded two record labels and produced music for Adele, Courtney Love, Christina Aguilera, and Alicia Keys.",
