        sort_time: "2026-11-19 20:30:00",
        end_time_formatted: "2026-11-19 23:59",
        detail: "The Composer\'s Room | Featuring the Music of Daniel Combs Thu, Nov 19 Joe Enright hosts a monthly Thursday night of intimate, ever-changing night of original music, spotlighting a different featured artist each month. Blending jazz with each artist’s unique voice, the evening weaves original compositions with a curated selection of their personal influences and favorite tunes. \n Anchored by one of the region’s most in-demand drummers, Composer’s Room offers a rare glimpse inside the creative process, where collaboration, experimentation, and storytelling take center stage. \n \n November Featured Artist: \n This month, Joe welcomes keyboardist Daniel Combs. Daniel Combs is a keyboardist and composer currently residing in Durham, NC. He can be found playing with a wide variety of bands and artists including Isaac Hadden, Butler Knowles Quartet, and the improvisational trio Bug Puncher (featuring bassist Matt Laird and drummer Kurt Stracener). \n \n As a composer he has recorded and performed his works with a diverse range of musicians. In 2025, he released a duo album featuring drummer Brady Kennedy, entitled \"Areas\". Using unique keyboards you may have never seen before, his sounds and textures will please those who are brave enough. \n \n Peter Dimery will be featured on tenor saxophone and effects for this show. \n \n Advance Reservations are Recommended. $10/Door. \n 07:00 PM SHOW 08:30 PM SHOW",
