        start_time: "8:00 PM",
        end_time: "?",
        name: `My Favorite Things | Shana Tucker Quartet`,
        sort_time: "2026-12-12 20:00:00",
        end_time_formatted: "2026-12-12 23:59",
        detail: "My Favorite Things | Shana Tucker Quartet Sat, Dec 12 Shana Tucker Quartet | Sat, Dec 12 | 8:00 & 9:30pm \n \n Join renowned vocalist, cellist and storyteller Shana Tucker and her dynamic piano trio for a festive return to Hotel Eve to celebrate the music of the holidays. Featuring Christmas classics, charming seasonal originals, jingle bell sing-alongs, and plenty of laughs, Shana’s song-storytelling is sure to spark joy to the world…or at least in the hearts of those present on this night! \n \n \"Meanwhile, beautiful intensity exudes from the “chambersoul” of Shana Tucker, a singer-songwriter whose main instrument is the cello. Her original gumbo of jazz, folk and R&B evokes the spirit of Bill Withers and Esperanza Spalding.\" — Sylvia Pfeiffenberger, INDYWEEK \n \n ||: www.shanatucker.com :|| \n \n Advance Reservations are Strongly Recommended | $15 \n 08:00 PM SHOW 09:30 PM SHOW",
